import{_ as r,o as d,c as a,a2 as e}from"./chunks/framework.CFuv5BrO.js";const b=JSON.parse('{"title":"Hearth OS · 主动式引擎设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/Hearth-主动式引擎设计说明.md","filePath":"architecture/Hearth-主动式引擎设计说明.md","lastUpdated":null}'),o={name:"architecture/Hearth-主动式引擎设计说明.md"};function h(s,t,n,l,i,c){return d(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="hearth-os-·-主动式引擎设计说明" tabindex="-1">Hearth OS · 主动式引擎设计说明 <a class="header-anchor" href="#hearth-os-·-主动式引擎设计说明" aria-label="Permalink to &quot;Hearth OS · 主动式引擎设计说明&quot;">​</a></h1><blockquote><p>本文只依据项目源码整理（<code>apps/server/src</code> 下主动建议、常驻意图、入站分拣、注意力、预备动作、看门狗、订阅与后台工具相关文件），未参考 <code>docs/</code> 与 <code>README.md</code>；文中不列举任何具体代码，括号内的文件名仅用于定位核对。 整理日期：2026-11-13</p></blockquote><p><strong>本文边界（避免与本套其它说明重复）</strong></p><table tabindex="0"><thead><tr><th>已讲过的内容</th><th>在哪份文档</th><th>本文的处理</th></tr></thead><tbody><tr><td>注意力提醒作为「需要用户参与」的第四类、防打扰限流结论</td><td><a href="./判定审批机制说明.html">判定审批机制说明</a></td><td>不重复治理结论，只补打分公式与影子模式等结构性事实</td></tr><tr><td>各后台周期任务的间隔对比</td><td><a href="./定时任务设计说明.html">定时任务设计说明</a></td><td>不重复</td></tr><tr><td>常驻意图在审批链路中的角色</td><td><a href="./判定审批机制说明.html">判定审批机制说明</a></td><td>只讲心跳循环本身</td></tr><tr><td>事件总线与接口注册</td><td><a href="./Hearth-服务组装与API接入设计说明.html">Hearth-服务组装与API接入设计说明</a></td><td>不展开</td></tr></tbody></table><p>本文只讲：<strong>系统怎么主动发现「有事该提醒你」、建议怎么产生与流转、以及一组后台守护服务如何兜底</strong>。</p><hr><h2 id="_0-一句话总览" tabindex="-1">0. 一句话总览 <a class="header-anchor" href="#_0-一句话总览" aria-label="Permalink to &quot;0. 一句话总览&quot;">​</a></h2><p>这一组服务把「事件流 + 周期扫描」转换成建议、注意力项、预备动作与看门狗事件，全部状态经事件溯源持久化。整体取向是<strong>默认只读、默认影子模式</strong>：能提示就不自动动手，能记一笔就不产生外部副作用。</p><hr><h2 id="_1-先定性-三个容易误解的地方" tabindex="-1">1. 先定性：三个容易误解的地方 <a class="header-anchor" href="#_1-先定性-三个容易误解的地方" aria-label="Permalink to &quot;1. 先定性：三个容易误解的地方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>代码里的实际做法</th></tr></thead><tbody><tr><td>以为「接受建议」就会自动建任务</td><td>接受只改状态；必须再调用「转为任务」才会真正创建任务</td></tr><tr><td>以为只有一套防打扰预算</td><td>主动建议与注意力项是<strong>两套独立闸门</strong>，两者每日上限数值恰好相同但互不相干</td></tr><tr><td>以为看门狗会直接取消卡死的任务</td><td>默认影子模式，只告警；「暂停」实际是把任务改成「可以继续」，不是删除</td></tr></tbody></table><hr><h2 id="_2-主动建议-三类触发器、六类扫描器" tabindex="-1">2. 主动建议：三类触发器、六类扫描器 <a class="header-anchor" href="#_2-主动建议-三类触发器、六类扫描器" aria-label="Permalink to &quot;2. 主动建议：三类触发器、六类扫描器&quot;">​</a></h2><p><strong>触发器</strong>同时存在三种：周期扫描、启动 5 秒后的首次扫描、以及订阅七类事件（任务创建/更新、审批创建/更新、效果更新、来源条目与来源更新）后的 2 秒防抖扫描。扫描整体被异常保护包住，一次失败不会中断后续定时；定时器都不阻止进程退出。</p><p><strong>六类扫描器</strong>各自产出带优先级与过期时间的候选：</p><table tabindex="0"><thead><tr><th>扫描器</th><th>发现什么</th><th>优先级 / 过期</th></tr></thead><tbody><tr><td>任务临近截止</td><td>24 小时窗口内到期</td><td>越近分越高，到截止时间过期</td></tr><tr><td>任务失败</td><td>失败或「可以继续」的任务</td><td>90，7 天过期</td></tr><tr><td>效果不确定</td><td>结果不确定的外部副作用</td><td>95、高风险、需审批、不过期</td></tr><tr><td>审批久拖</td><td>挂起超过 2 小时的审批</td><td>85、需审批</td></tr><tr><td>来源新条目</td><td>近 24 小时就绪的条目</td><td>40，3 天过期</td></tr><tr><td>系统健康</td><td>排队过多或运行过久</td><td>70，1 小时过期</td></tr></tbody></table><p><strong>去重与合并</strong>是这套设计的重点：每个候选有固定去重键。已存在时按原状态分别处理——被忽略的只累加出现次数与证据、不再复活；稍后提醒的未到点只累加、过了点重置为新建议；已接受/已转任务只累加；已过期的重置为新建议并清空首次出现时间。也就是说<strong>被忽略是终态语义</strong>，不会因为事情再次发生而反复弹出来烦人。</p><p>建议有六种状态：新、已接受、已忽略、稍后提醒、已转任务、已过期。投递闸门检查暂停状态、免打扰时段、冷却窗口，再把「新且未通知过」的建议按优先级降序逐条投递，直到用掉当日额度（默认 5 条）。默认免打扰是晚 22 点至早 8 点，默认冷却 60 分钟。</p><p>另有预算与指标：以 7 天为窗口统计接受率与「每个完成任务被打断几次」。</p><hr><h2 id="_3-常驻意图-心跳与交付闸门" tabindex="-1">3. 常驻意图：心跳与交付闸门 <a class="header-anchor" href="#_3-常驻意图-心跳与交付闸门" aria-label="Permalink to &quot;3. 常驻意图：心跳与交付闸门&quot;">​</a></h2><p>常驻意图是用户设下的「以后只要出现 X 就提醒我」，状态有六种：待激活、已激活、已触发、已完成、已取消、已过期。创建时默认激活，可设冷却（默认 24 小时）、最多触发次数（默认 3 次）、90 天过期；触发条件是 1–20 条规则，每条 1–20 个关键词，支持「全部命中 / 任一命中」；还可以限定渠道、发件人、任务、目标作用域。</p><p>匹配时只取已激活与已触发的前 256 条，先处理过期与冷却复位，再按作用域、冷却、触发次数上限过滤。中文关键词用包含匹配，拉丁词用词边界匹配。命中后触发次数加一，达到上限就置「已完成」，并生成一条注意力项。</p><p><strong>心跳会扫九类信号</strong>：等待补充的任务、停滞超 30 分钟的任务、待审批、目标到期、72 小时内到期的承诺、效果不确定、需人工对账、来源需要用户处理、来源新条目；若带文本还会做一次意图匹配。每次心跳留一条运行记录，包含触发类型、决定的注意力编号、以及「通知 / 不通知」的结论与原因。</p><p>交付闸门有明确顺序：<strong>关键项直接放行且不计入预算</strong> → 免打扰 → 每日上限 → 每个目标每日上限 → 高优先级每日上限；此外还有全局冷却窗口。记录完决定后才调用外部投递，传输失败不会抹掉已记录的决定。</p><hr><h2 id="_4-入站分拣-四类结果" tabindex="-1">4. 入站分拣：四类结果 <a class="header-anchor" href="#_4-入站分拣-四类结果" aria-label="Permalink to &quot;4. 入站分拣：四类结果&quot;">​</a></h2><p>外部来信先用正则分到忽略、闲聊、任务、需关注四类，优先级依次判定：</p><ol><li><strong>忽略</strong>：退订、自动回复、请勿回复、简报、空内容、纯表情，置信度 0.95；</li><li><strong>需关注</strong>：验证码、截止/紧急、冲突、密码与密钥、付款合同、审批签字，命中越多置信度越高（封顶 0.95）；</li><li><strong>任务</strong>：请求动词 + 动作动词，且文本长度达标，置信度随命中数上升（封顶 0.92）；</li><li><strong>闲聊</strong>：寒暄、疑问句、短文本，或兜底。</li></ol><p>高优先级发件人（老板、客户、VIP）会额外加一个信号与少量置信度加成。每条决策留一条记录，包含来源引用、去向、理由（命中信号拼接）、两位小数置信度，并生成一个指纹用于去重。</p><blockquote><p>注意：这只写一条决策记录，<strong>不选择执行器</strong>；执行器自动选择是另一条链路，见<a href="./意图识别路由与执行器自动选择.html">意图识别路由与执行器自动选择</a>。</p></blockquote><hr><h2 id="_5-预备动作-先备好-不擅自执行" tabindex="-1">5. 预备动作：先备好，不擅自执行 <a class="header-anchor" href="#_5-预备动作-先备好-不擅自执行" aria-label="Permalink to &quot;5. 预备动作：先备好，不擅自执行&quot;">​</a></h2><p>预备动作有五种类型：邮件草稿、日程检查、调研、试运行、差异查看。记录包含任务/目标编号、动作摘要（对类型与预览做稳定序列化后的指纹）、预览、状态、24 小时后过期、证据引用。创建时强制要求证据引用非空。</p><p>提交时的规则值得注意：<strong>邮件草稿与日程检查属于外部动作，必须绑定一条已批准且任务一致的审批，并比对动作指纹</strong>，防止「拿 A 的审批去执行 B」；而调研、试运行、差异查看三类无需审批即可提交。状态为已准备、已提交、已丢弃、已过期。</p><hr><h2 id="_6-看门狗-默认只告警" tabindex="-1">6. 看门狗：默认只告警 <a class="header-anchor" href="#_6-看门狗-默认只告警" aria-label="Permalink to &quot;6. 看门狗：默认只告警&quot;">​</a></h2><p>看门狗每分钟扫一次，找四类问题：任务停滞（运行中且超过 30 分钟没更新）、运行超预算（超过 120 分钟）、重复失败（一小时内 3 次带失败的运行）、后台工具失败。每类发现按去重窗口（默认 60 分钟）避免重复记录。</p><p>默认配置是「影子模式开启、自动取消关闭」：所有发现只产生告警，不会真的暂停；若关掉影子模式，部分发现会变成「暂停」，即把运行中的任务改为「可以继续」。只有显式打开自动取消，关键发现才会升级为取消。发现会记录成事件，并可生成一条「受阻」注意力项。</p><hr><h2 id="_7-订阅投递与后台工具" tabindex="-1">7. 订阅投递与后台工具 <a class="header-anchor" href="#_7-订阅投递与后台工具" aria-label="Permalink to &quot;7. 订阅投递与后台工具&quot;">​</a></h2><p><strong>订阅投递</strong>服务在<strong>构造时</strong>就订阅事件总线（没有对称的启动方法，只有关闭）。订阅按会话键与任务复用，支持类型白名单（可用前缀通配）与黑名单；投递是内存监听器扇出、推进游标、最近 500 条记录在内存里，<strong>不是持久化消息队列</strong>。它还会跳过自身前缀的事件，防止自激。</p><p><strong>后台工具</strong>服务允许 Agent 把耗时工具放到后台跑：默认并发 2（上限 8）、超时 10 分钟、输出上限 6.4 万字符。启动前检查任务未终态、工具在权限名单内、非只读工具必须有授权回调、并发未满。授权是在持久化之前等待的，且并发上限在授权前后各检查一次（防止等待期间被占满）。任务状态为排队 → 运行 → 完成/失败/已停止；超时通过取消信号中止。对外暴露两个工具：启动后台工具（立即返回编号）与查询后台工具。</p><hr><h2 id="_8-注意力打分-结构性补充" tabindex="-1">8. 注意力打分（结构性补充） <a class="header-anchor" href="#_8-注意力打分-结构性补充" aria-label="Permalink to &quot;8. 注意力打分（结构性补充）&quot;">​</a></h2><p>治理结论见<a href="./判定审批机制说明.html">判定审批机制说明</a>，这里只补公式：得分由优先级（数值越小分越高）、紧迫度（按存在小时数增长）、影响度（按类型取固定上限，对账/截止/决定类最高）、等待对象（等用户加分、等 Agent 减分）、关键项加成、可逆性、以及反馈偏置七项相加。反馈偏置需要累计足够样本才生效，负反馈多则减分、正反馈多则加分。列表会对同一聚合键只保留最高分，其余标记为被遮蔽。</p><p>影子模式与看门狗的影子模式是<strong>两个独立开关</strong>，默认值还不一样：注意力治理默认不开影子，看门狗默认开。</p><hr><h2 id="_9-只读代码才会发现的事实" tabindex="-1">9. 只读代码才会发现的事实 <a class="header-anchor" href="#_9-只读代码才会发现的事实" aria-label="Permalink to &quot;9. 只读代码才会发现的事实&quot;">​</a></h2><ol><li>接受建议不建任务，必须再「转为任务」；被忽略的建议不会复活。</li><li>两套投递闸门彼此独立；关键项在注意力预算里被完全豁免。</li><li>看门狗的「暂停」是把任务改为「可以继续」，不是取消或删除。</li><li>外部类预备动作提交时强制比对审批与动作指纹，内部三类不需要审批。</li><li>订阅投递构造即订阅、内存扇出、只留 500 条，不是可靠队列。</li><li>后台工具的并发上限在授权前后检查两次，授权本身可接收取消信号。</li></ol><hr><h2 id="_10-与其它模块的分界" tabindex="-1">10. 与其它模块的分界 <a class="header-anchor" href="#_10-与其它模块的分界" aria-label="Permalink to &quot;10. 与其它模块的分界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>内容</th></tr></thead><tbody><tr><td>输入</td><td>事件总线与事件存储、任务/审批/效果/来源/目标/承诺/后台任务记录、装配时注入的交付闸门与通知器</td></tr><tr><td>输出</td><td>建议与注意力项、心跳运行记录、入站决策、预备动作、看门狗事件、订阅投递、后台工具 job</td></tr><tr><td>不讲</td><td>防打扰治理结论与用户在哪里回答（判定审批）、定时器间隔对比（定时任务）、事件总线与端点注册（服务组装）</td></tr></tbody></table><hr><h2 id="附-源码定位索引" tabindex="-1">附：源码定位索引 <a class="header-anchor" href="#附-源码定位索引" aria-label="Permalink to &quot;附：源码定位索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想看什么</th><th>去哪找</th></tr></thead><tbody><tr><td>建议扫描、去重合并、状态与投递</td><td><code>apps/server/src/proactive.ts</code></td></tr><tr><td>常驻意图、心跳信号与交付闸门</td><td><code>apps/server/src/standing-intents.ts</code></td></tr><tr><td>入站四类分拣</td><td><code>apps/server/src/intake-router.ts</code></td></tr><tr><td>注意力打分与影子模式</td><td><code>apps/server/src/attention-governor.ts</code></td></tr><tr><td>预备动作与审批绑定</td><td><code>apps/server/src/prepared-actions.ts</code></td></tr><tr><td>看门狗判据与动作</td><td><code>apps/server/src/watchdog.ts</code></td></tr><tr><td>订阅投递</td><td><code>apps/server/src/thread-subscriptions.ts</code></td></tr><tr><td>后台工具并发与超时</td><td><code>apps/server/src/background-tools.ts</code></td></tr><tr><td>相关契约类型</td><td><code>packages/core/src/types.ts</code>、<code>personal-agent.ts</code></td></tr></tbody></table>',56)])])}const _=r(o,[["render",h]]);export{b as __pageData,_ as default};
